def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C'

    # count opponent's cooperation/defection
    opp_c = 0
    my_c = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
    opp_d = n - opp_c

    # Against an always-cooperative opponent, exploit near the end.
    if opp_d == 0:
        if n >= 90:
            return 'D'
        return 'C'

    # Detect current opponent defection streak.
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    # Detect current cooperation streak.
    cstreak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cstreak += 1
        else:
            break

    # If opponent is heavily defecting, mostly punish but probe occasionally.
    if opp_d * 2 > n and n >= 8:
        if streak >= 5:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent has just defected.
    if opp_last == 'D':
        # Long defection streak: punish strongly, rare cooperation test.
        if streak >= 4:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        # Forgiving Tit-for-Tat: mostly defect, some chance to restore cooperation.
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent last cooperated.
    if opp_last == 'C':
        # Long cooperation streak: exploit late, otherwise cooperate.
        if cstreak >= 5:
            if n < 92 and rng.random() < 0.05:
                return 'D'
            return 'C'
        # If we defected last turn after opponent cooperation, likely continue cooperation.
        if my_last == 'D':
            if n < 95 and rng.random() < 0.15:
                return 'D'
            return 'C'
        return 'C'
